package app.unifeed.media;
import app.unifeed.error.*; import java.io.*; import java.nio.file.*; import java.time.LocalDate; import java.util.*; import net.coobird.thumbnailator.Thumbnails; import org.apache.tika.Tika; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile;
@Service public class MediaStorageService {private final Path root;private final long avatarLimit,postLimit,clubLimit;private final Tika tika=new Tika();public MediaStorageService(@Value("${app.storage.uploads-root:uploads}")String root,@Value("${app.storage.avatar-max-size-bytes}")long avatar,@Value("${app.storage.post-media-max-size-bytes}")long post,@Value("${app.storage.club-cover-max-size-bytes}")long club){this.root=Path.of(root).toAbsolutePath().normalize();avatarLimit=avatar;postLimit=post;clubLimit=club;}
 public MediaPaths store(MultipartFile file,Category category)throws IOException{if(file.getSize()>limit(category))throw new BusinessException(ErrorCode.COMMON_409_CONFLICT,HttpStatus.PAYLOAD_TOO_LARGE);byte[] bytes=file.getBytes();String mime=tika.detect(bytes);if(!Set.of("image/jpeg","image/png","image/webp").contains(mime))throw new BusinessException(ErrorCode.COMMON_409_CONFLICT,HttpStatus.UNSUPPORTED_MEDIA_TYPE);LocalDate d=LocalDate.now();Path dir=root.resolve(category.folder).resolve("%04d".formatted(d.getYear())).resolve("%02d".formatted(d.getMonthValue()));Files.createDirectories(dir);String base=UUID.randomUUID().toString();Path original=dir.resolve(base+"-original.jpg"),medium=dir.resolve(base+"-medium.jpg"),thumb=dir.resolve(base+"-thumb.jpg");try(InputStream in=new ByteArrayInputStream(bytes)){Thumbnails.of(in).size(1920,1920).outputFormat("jpg").outputQuality(.85).toFile(original.toFile());}Thumbnails.of(original.toFile()).size(600,600).outputFormat("jpg").outputQuality(.85).toFile(medium.toFile());Thumbnails.of(original.toFile()).size(150,150).outputFormat("jpg").outputQuality(.85).toFile(thumb.toFile());return new MediaPaths(uri(thumb),uri(medium),uri(original));}
 private long limit(Category category){return switch(category){case AVATAR->avatarLimit;case CLUB->clubLimit;case POST,STORY->postLimit;};}
 private String uri(Path p){return "/uploads/"+root.relativize(p).toString().replace('\\','/');}public enum Category{AVATAR("avatars"),POST("posts"),STORY("stories"),CLUB("clubs");final String folder;Category(String f){folder=f;}}public record MediaPaths(String thumbnailPath,String mediumPath,String originalPath){}
}
